import { HttpClient, HttpHeaders } from '@angular/common/http';
import { inject, Injectable, makeStateKey, PLATFORM_ID, TransferState } from '@angular/core';
import { lastValueFrom, map } from 'rxjs';
import { User } from '../../interfaces/user.interface';
import { SessionService } from '../session/session.service';

@Injectable({
  providedIn: 'root'
})
export class GitApiService {
  private baseUrl = 'https://api.github.com';
  public token = '';//'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';

  constructor(
    private http: HttpClient,
    private sessionService: SessionService,
  ) {
  }

  private async getHeaders(){
    const token = await this.sessionService.getSession('token');
    return new HttpHeaders({
      Authorization: `Bearer ${token}`,
      Accept: 'application/vnd.github.full+json'
    });
  }

  requestAccessToken(code: string): Promise<any>{
    return lastValueFrom(this.http.post('http://localhost:3000/api/exchange-token', { code }, {
      headers: { 'Content-Type': 'application/json' }
    }));
  }

  async listRepositories(data: any): Promise<any>{
    const url = `${this.baseUrl}/user/repos`;
    return lastValueFrom(
      this.http.get(url, { 
        headers: await this.getHeaders(),
        params: data.params
      })
    ).then((response: any) => {
      const filteredRepos = response.filter((repo: any) => repo.owner.login === data.owner);

      return filteredRepos;
    });
  }

  async listIssuesAssigned(data: any): Promise<any>{
    const url = `${this.baseUrl}/issues`;
    
    return lastValueFrom(
      this.http.get(url, { 
        headers: await this.getHeaders(), 
        params: { state: "open", sort: "updated", direction: "desc" }
      })
    ).then((response: any) => {
      const filteredIssues = response.filter((issue: any) => !issue.pull_request).filter((issue: any) => issue.repository.owner.login === data.owner);
      console.log(filteredIssues);

      return filteredIssues;
    });
  }

  async listRepositoryIssues(name: string): Promise<any>{
    const url = `${this.baseUrl}/repos/${name}/issues`;

    return lastValueFrom(
      this.http.get(url, { 
        headers: await this.getHeaders(), 
        params: { state: "open" }
      })
    ).then((response: any) => {
      const filteredIssues = response.filter((issue: any) => !issue.pull_request);

      return filteredIssues;
    });
  }

  async listRepositoryPullRequest(name: string): Promise<any>{
    const url = `${this.baseUrl}/repos/${name}/pulls`;
    return lastValueFrom(this.http.get(url, { headers: await this.getHeaders() }));
  }

  async getAuthUserInformation(){
    const url = `${this.baseUrl}/user`;
    return lastValueFrom(
      this.http.get(url, { headers: await this.getHeaders() }).pipe(
        map((response: any) => {
          return {
            avatar_url: response.avatar_url,
            bio: response.bio,
            id: response.id,
            login: response.login,
          } as User;
        })
      ));
  }

  async sendRequest(url: string):Promise<any>{
    return lastValueFrom(
      this.http.get(url, { headers: await this.getHeaders() })
    );
  }

  async listAssignees(name: string){
    const url = `${this.baseUrl}/repos/${name}/assignees`;
    return lastValueFrom(this.http.get(url, { headers: await this.getHeaders() }));
  }

  async createIssue(name: string, param: any): Promise<any>{
    const url = `${this.baseUrl}/repos/${name}/issues`;
    return lastValueFrom(this.http.post(url, param, { headers: await this.getHeaders(), observe: 'response' }));
  }

  async listLabels(name: string){
    const url = `${this.baseUrl}/repos/${name}/labels`;
    return lastValueFrom(this.http.get(url, { headers: await this.getHeaders() }));
  }

  async getRepositoryReadme(name: string){
    const url = `${this.baseUrl}/repos/${name}/readme`;
    return lastValueFrom(this.http.get(url, { headers: await this.getHeaders() }));
  }

  async updateIssue(url: string, params: any): Promise<any>{
    return lastValueFrom(this.http.patch(url, params, {
      headers: await this.getHeaders()
    }))
  }

 async getApiDocs() {
  const url = `${this.baseUrl}/repos/marhano/api-docs/contents/docs`;

  try {
    // Fetch the list of files in the 'docs' folder
    const result: any[] = await lastValueFrom(this.http.get<any[]>(url, { headers: await this.getHeaders() }));

    // Filter for JSON files
    const jsonFiles = result.filter((item) => item.type === 'file' && item.name.endsWith('.json'));

    if (jsonFiles.length > 0) {
      
      const docs: any[] = [];

      for (const element of jsonFiles) {
        docs.push(element.name);
      }
      // Fetch the contents of the first JSON file


      return docs;
    } else {
      console.warn('No JSON files found in the specified folder.');
      return null;
    }
  } catch (error) {
    console.error('Error fetching API docs:', error);
    throw error; // Re-throw the error for further handling
  }
}

async getApiDocFile(name: string){
  const url = `${this.baseUrl}/repos/marhano/api-docs/contents/docs/${name}`;
  return lastValueFrom(this.http.get(url, { headers: await this.getHeaders() })).then((response: any) => {
    const decodedContent = atob(response.content);

    return JSON.parse(decodedContent);
  });
}

}

import { Injectable } from '@angular/core';
import { SessionService } from '../session/session.service';

@Injectable({
  providedIn: 'root'
})
export class IssueTrackerService {

  constructor(
    private sessionService: SessionService
  ) { }

  async getIssueTrackerDataBy(){
    return await this.sessionService.getSession('viewed');
  }

  async getIssueTrackerDataById(id: number){
    const issueTrackerData = await this.sessionService.getSession('viewed');
    if(issueTrackerData){
      return issueTrackerData.find((issue: any) => issue.id === id);
    }
    return null;
  }

  async setIssueTrackerDataById(data: any){
    const url = this.extractRepositoryName(data.url);
    console.log(url);
    const issueTrackerData = await this.sessionService.getSession('viewed');
    if(issueTrackerData){

      if(issueTrackerData[url.owner] && issueTrackerData[url.owner][url.repo]){
        const issueIndex = issueTrackerData[url.owner][url.repo].findIndex((issue: any) => issue === data.id);
        if(issueIndex !== -1){
          console.log('Issue already exists in the array.');
          return;
        }
        issueTrackerData[url.owner][url.repo].push(data.id);

        await this.sessionService.setSession({ viewed: issueTrackerData });
        return;
      }
      if(issueTrackerData[url.owner]){
        issueTrackerData[url.owner][url.repo] = [data.id];
        await this.sessionService.setSession({ viewed: issueTrackerData });
        return;
      }
    }

    await this.sessionService.setSession({ viewed: {
      [url.owner]: {
        [url.repo]: [data.id]
      }
    } });
  }

  extractRepositoryName(url: string): { owner: string, repo: string} {
    const urlParts = url.split('/');
    const repoIndex = urlParts.indexOf('repos') + 1;

    return {
      owner: urlParts[repoIndex],
      repo: urlParts[repoIndex + 1]
    };
  }

  

}

import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { lastValueFrom } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class JsonService {
  private nodeApiUrl = 'http://localhost:4000/api/session';

  constructor(
    private http: HttpClient
  ) { }

  getItem(key: string): Promise<any>{
    return lastValueFrom(this.http.get(`${this.nodeApiUrl}/${key}`));
  }

  setItem(key: string, value: any): Promise<any>{
    return lastValueFrom(this.http.post(this.nodeApiUrl, { key, value }));
  }

  removeItem(key: string): Promise<any>{
    return lastValueFrom(this.http.delete(`${this.nodeApiUrl}/${key}`));
  }

  getAll(): Promise<any>{
    return lastValueFrom(this.http.get(this.nodeApiUrl));
  }
}

import { Injectable } from '@angular/core';
import { JsonService } from '../json/json.service';

@Injectable({
  providedIn: 'root'
})
export class SessionService {
  private key: string = 'reposync__dev__session';

  constructor(
    private jsonService: JsonService,
  ) { 
  }

  async setSession(newData: { [key: string]: any }){
    const currentData = await this.getSession();

    const updatedData = { ...currentData, ...newData };
    
    localStorage.setItem(this.key, JSON.stringify(updatedData));
  }

  async getSession(key?: string): Promise<any>{
    const storedDatas = localStorage.getItem(this.key) as any;
    let storedData;
    if(storedDatas){
      storedData = JSON.parse(storedDatas);
    }
    
    if(!storedData){
      return key ? null : {};
    }

    return key ? storedData[key] : storedData;
  }

  async removeSession(key?: string): Promise<any>{
    const storedDatas = localStorage.getItem(this.key);
    if (!storedDatas) return;

    const storedData = JSON.parse(storedDatas);

    if (key) {
      delete storedData[key];
      localStorage.setItem(this.key, JSON.stringify(storedData));
    } else {
      localStorage.removeItem(this.key);
    }
  }
}

