import { ChangeDetectorRef, Component, ElementRef, inject, input, QueryList, resource, ViewChildren } from '@angular/core';
import { MatTabsModule } from '@angular/material/tabs';
import { FontAwesomeModule } from '@fortawesome/angular-fontawesome';
import { MarkdownModule } from 'ngx-markdown';
import * as Prism from 'prismjs';
import 'prismjs/components';
import 'prismjs/plugins/toolbar/prism-toolbar.js';
import 'prismjs/plugins/line-highlight/prism-line-highlight.js';
import { GitApiService } from '../../services/git-api/git-api.service';
import { fromEvent, throttleTime } from 'rxjs';

@Component({
  selector: 'app-api-docs',
  imports: [
    FontAwesomeModule,
    MarkdownModule,
    MatTabsModule
  ],
  templateUrl: './api-docs.component.html',
  styleUrl: './api-docs.component.scss'
})
export class ApiDocsComponent {
  @ViewChildren('section') sections!: QueryList<ElementRef>;
  public active: string = '';

  id = input<string>();

  docs = resource({
    request: this.id,
    loader: ({ request: id }) => this.gitApiService.getApiDocFile(id) 
  });

  private gitApiService = inject(GitApiService);

  async ngOnInit() {
    setTimeout(() => {
      Prism.highlightAll();
    }, 200);

    const container = document.querySelector('.container') as HTMLElement;

    if(container){
      fromEvent(container, 'scroll')
        .pipe(throttleTime(100))
        .subscribe(() => {
          console.log('throttle');
          this.updateActiveSection(container);
        });
    }
  }

  private updateActiveSection(container: HTMLElement){
    for (const section of this.sections) {
      const rect = section.nativeElement.getBoundingClientRect();
      const containerRect = container.getBoundingClientRect();

      if (rect.top >= containerRect.top && rect.top < containerRect.bottom) {
        this.active = section.nativeElement.id;
        break;
      }
    }
  }

  onTabChange(){
    setTimeout(() => {
      Prism.highlightAll();
    }, 100);
  }

  scrollToSection(sectionId: string){
    const section = document.getElementById(sectionId) as HTMLElement;
    const container = section?.closest('.container') as HTMLElement;

    
    if (section && container) {
      container.scrollTo({
        top: section.offsetTop - container.offsetTop + 16,
        behavior: 'instant'
      });
    }
  }

  collpaseSidebar(){
    const sidebar = document.querySelector('aside') as HTMLElement;
    sidebar.classList.toggle('collapsed');
    const uncollapsed = document.querySelector('.uncollapse-sidebar') as HTMLElement;
    uncollapsed.classList.toggle('show');
  }

  uncollpaseSidebar(){
    const sidebar = document.querySelector('aside') as HTMLElement;
    sidebar.classList.remove('collapsed');
    const uncollapsed = document.querySelector('.uncollapse-sidebar') as HTMLElement;
    uncollapsed.classList.remove('show');
  }

}

import { Component, inject, resource } from '@angular/core';
import { GitApiService } from './services/git-api/git-api.service';
import { Router, RouterLink, RouterLinkActive, RouterOutlet } from '@angular/router';
import { ElectronService } from 'ngx-electronyzer';
import { MatDialog } from '@angular/material/dialog';
import { UpdateDialogComponent } from './components/update-dialog/update-dialog.component';
import { UpdateInfo } from './interfaces/update-info.interface';
import { WindowNavBarComponent } from './components/window-nav-bar/window-nav-bar.component';
import { MatIconModule } from '@angular/material/icon';
import { CommonModule } from '@angular/common';
import { SessionService } from './services/session/session.service';
import { environment } from '../environments/environment';
import { FaIconLibrary, FontAwesomeModule } from '@fortawesome/angular-fontawesome';
import { fas } from '@fortawesome/free-solid-svg-icons';
import { far } from '@fortawesome/free-regular-svg-icons';

@Component({
  selector: 'app-root',
  imports: [
    RouterOutlet,
    RouterLink,
    RouterLinkActive,
    WindowNavBarComponent,
    MatIconModule,
    CommonModule,
    FontAwesomeModule
  ],
  templateUrl: './app.component.html',
  styleUrl: './app.component.scss',
  providers: [
    GitApiService
  ],
  standalone: true,
})
export class AppComponent {
  title = 'repo-sync';
  public showSidebar: boolean = true; 
  public appVersion = environment.APP_VERSION;

  private gitApiService = inject(GitApiService);
  
  docsResource = resource({
    loader: () => this.gitApiService.getApiDocs()
  });
 
  constructor(
    private electronService: ElectronService,
    private dialog: MatDialog,
    private router: Router,
    private sessionService: SessionService,
    private library: FaIconLibrary
  ){

    library.addIconPacks(fas, far);

    if(this.electronService.isElectronApp){
      this.electronService.ipcRenderer.on('update-available', (_: any, data: any) => {
        // dialog to display release notes and to download the available updates
       
      });

      this.electronService.ipcRenderer.on('update-downloaded', (_:any, data: UpdateInfo) => {
        // dialog to install the updates
        this.dialog.open(UpdateDialogComponent, {
          width: '600px',
          data: data
        });
      });
    }

    this.router.events.subscribe(() => {
      this.toggleSidebar();
    });
  }

  toggleSidebar(){
    const excludedRoutes = ['/login', '/authorize', '/issue'];

    const path = this.router.parseUrl(this.router.url).root.children['primary']?.segments.map(segment => segment.path).join('/');
    this.showSidebar = !excludedRoutes.includes(`/${path}`);
  }

  transformItemName(item: string): string {
    return item
      .replace('.json', '') // Remove the .json extension
      .replace(/-/g, ' ') // Replace hyphens with spaces
      .replace(/\b\w/g, (char) => char.toUpperCase()); // Capitalize each word
  }

  async ngAfterViewInit(){

    //const user = await this.gitApiService.getAuthUserInformation();
    // Set default repo owner
    this.sessionService.setSession({ owner: 'marhano' });
    const mode = await this.sessionService.getSession('darkMode');
    const theme = await this.sessionService.getSession('theme');

    const container = document.querySelector('html') as HTMLElement;

    if(mode){
      container.classList.add('dark-mode');
    }else{
      container.classList.remove('dark-mode');
    }

    if(theme){
      container.classList.forEach((className) => {
        if (className.includes('palette')) {
          container.classList.remove(className);
        }
      });
  
      container.classList.add(theme);
    }
  }
}

import { CommonModule, isPlatformBrowser } from '@angular/common';
import { Component, inject, OnInit, PLATFORM_ID } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { GitApiService } from '../../services/git-api/git-api.service';
import { SessionService } from '../../services/session/session.service';
import { ActivatedRoute, Router } from '@angular/router';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { WindowNavBarComponent } from '../../components/window-nav-bar/window-nav-bar.component';
import { ElectronService } from 'ngx-electronyzer';

@Component({
  selector: 'app-authorize',
  imports: [
    MatButtonModule,
    CommonModule,
    FormsModule,
    MatProgressSpinnerModule,
    WindowNavBarComponent
  ],
  templateUrl: './authorize.component.html',
  styleUrl: './authorize.component.scss'
})
export class AuthorizeComponent implements OnInit{
  public errorDescription: string | null = '';

  constructor(
    private gitApiService: GitApiService,
    private sessionService: SessionService,
    private router: Router,
    private route: ActivatedRoute,
    private electronService: ElectronService
  ){
    
  }

  async ngOnInit(): Promise<void> {
    try{
      const token = await this.sessionService.getSession('token');
      if(token){
        this.gitApiService.token = token;
        this.router.navigate(['/dashboard']);
        return;
      }

      if(this.electronService.isElectronApp){
        this.electronService.ipcRenderer.on('auth-success', async (_: any, token: any) => {
          await this.sessionService.setSession({
            token: token.access_token
          });

          this.gitApiService.token = token;
          setTimeout(() => {
            this.router.navigate(['/dashboard']);
          }, 2000);
        });
      }else{
        this.errorDescription = new URLSearchParams(window.location.search).get('error_description');
        const code = new URLSearchParams(window.location.search).get('code');

        if(code){
          console.log(code);
          const token = await this.gitApiService.requestAccessToken(code);
          await this.sessionService.setSession({
            token: token.access_token
          });
          this.gitApiService.token = token;
          setTimeout(() => {
            this.router.navigate(['/dashboard']);
          }, 2000);
        }
      }

    }catch(error){
      console.log(error);
    }
  }

}

import { CommonModule } from '@angular/common';
import { Component, Input, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'storybook-button',
  standalone: true,
  imports: [CommonModule],
  template: ` <button
  type="button"
  (click)="onClick.emit($event)"
  [ngClass]="classes"
  [ngStyle]="{ 'background-color': backgroundColor }"
>
  {{ label }}
</button>`,
  styleUrls: ['./button.css'],
})
export class ButtonComponent {
  /** Is this the principal call to action on the page? */
  @Input()
  primary = false;

  /** What background color to use */
  @Input()
  backgroundColor?: string;

  /** How large should the button be? */
  @Input()
  size: 'small' | 'medium' | 'large' = 'medium';

  /**
   * Button contents
   *
   * @required
   */
  @Input()
  label = 'Button';

  /** Optional click handler */
  @Output()
  onClick = new EventEmitter<Event>();

  public get classes(): string[] {
    const mode = this.primary ? 'storybook-button--primary' : 'storybook-button--secondary';

    return ['storybook-button', `storybook-button--${this.size}`, mode];
  }
}

