import { SessionService } from '../../services/session/session.service';
import { GitApiService } from '../../services/git-api/git-api.service';
import { Router } from '@angular/router';
import { isPlatformBrowser } from '@angular/common';
import { WindowNavBarComponent } from '../../components/window-nav-bar/window-nav-bar.component';

@Component({
  selector: 'app-login',
  imports: [
    MatFormFieldModule,
    MatInputModule,
    MatButtonModule,
    MatIconModule,
    WindowNavBarComponent
  ],
  templateUrl: './login.component.html',
  styleUrl: './login.component.scss'
})
export class LoginComponent implements OnInit{
  appVersion: string = environment.APP_VERSION;
  private isBrowser!:boolean;

  private platformId = inject(PLATFORM_ID);

  constructor(
    private sessionService: SessionService,
    private gitApiService: GitApiService,
    private router: Router
  ){
    this.isBrowser = isPlatformBrowser(this.platformId);
  }
  async ngOnInit(){
    const token = await this.sessionService.getSession('token');
    if(token){
      this.gitApiService.token = token;
      this.router.navigate(['/dashboard']);
    }
  }

  githubAuth(){
    const authUrl = `https://github.com/login/oauth/authorize?client_id=${environment.CLIENT_ID}&scope=repo,user`;
    if(this.isBrowser){
      window.location.href = authUrl;
    }else{
      console.log('Server-side execution, skipping window-based logic');
    }
    
  }

}

import { CommonModule } from '@angular/common';
import { Component, Input } from '@angular/core';
import { FormControl, FormsModule, ReactiveFormsModule } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MarkdownModule } from 'ngx-markdown';

@Component({
  selector: 'app-markdown-editor',
  imports: [
    MatIconModule,
    MarkdownModule,
    CommonModule,
    FormsModule,
    MatButtonModule,
    ReactiveFormsModule,
  ],
  templateUrl: './markdown-editor.component.html',
  styleUrl: './markdown-editor.component.scss'
})
export class MarkdownEditorComponent {
  @Input() control!: FormControl;

  activeTab: string = 'write';
  markdownContent: string = ``;

  ngOnInit(){
    if(!this.control){
      this.control = new FormControl();
    }
  }

  activateTab(tab: string){
    this.activeTab = tab;
  }

  insertMarkdown(markdown: string) {
    const textarea = document.querySelector('textarea') as HTMLTextAreaElement;
    const selectionStart = textarea.selectionStart;
    const selectionEnd = textarea.selectionEnd;

    const selectedText = this.markdownContent.slice(selectionStart, selectionEnd);

    const leadingSpace = selectedText.match(/^\s+/)?.[0] || '';
    const trailingSpace = selectedText.match(/\s+$/)?.[0] || '';

    let wrappedText: string;

    if(markdown === '###'){
      wrappedText = `${leadingSpace}${markdown} ${selectedText.trim()}${trailingSpace}`;
    }else{
      wrappedText = `${leadingSpace}${markdown}${selectedText.trim()}${markdown}${trailingSpace}`;
    }
   

    const textBefore = this.markdownContent.slice(0, selectionStart);
    const textAfter = this.markdownContent.slice(selectionEnd);

    this.markdownContent = textBefore + wrappedText + textAfter;

    setTimeout(() => {
      textarea.selectionStart = selectionStart;
      textarea.selectionEnd = selectionStart + wrappedText.length;
    }, 0);
  }

  autoResize(event: any) {
    const textarea = event.target as HTMLTextAreaElement;
    textarea.style.height = 'auto'; // Reset height to auto for accurate calculation
    textarea.style.height = `${textarea.scrollHeight}px`; // Set height based on content
  }

}

import { Component, inject, Input } from '@angular/core';
import { FaIconLibrary, FontAwesomeModule } from '@fortawesome/angular-fontawesome';
import { fas } from '@fortawesome/free-solid-svg-icons';
import { far } from '@fortawesome/free-regular-svg-icons';
import { Router, RouterLink, RouterLinkActive } from '@angular/router';

@Component({
  selector: 'app-menu',
  imports: [
    FontAwesomeModule,
    RouterLink,
    RouterLinkActive,
  ],
  templateUrl: './menu.component.html',
  styleUrl: './menu.component.scss'
})
export class MenuComponent {
  @Input() model!: any;

  private library = inject(FaIconLibrary);
  private route = inject(Router)

  constructor() {
    this.library.addIconPacks(fas, far);
  }

  openAccordion(event: any){
    console.log('expand');
    const target = event.target as HTMLElement;
    const parent = target.closest('.menu-item') as HTMLElement;

    if(parent){
      const submenu = parent.querySelector('.menu-submenu') as HTMLElement;

      if(submenu){
       if(submenu.classList.contains('expanded')){
        submenu.style.height = `${submenu.scrollHeight}px`;
        requestAnimationFrame(() => {
          submenu.style.height = '0';
        }); 
        submenu.classList.remove('expanded');
       }else{
        submenu.style.height = '0';
        submenu.classList.add('expanded');
        requestAnimationFrame(() => {
          submenu.style.height = `${submenu.scrollHeight}px`;
        });
       }
      }
    }
    console.log(target, parent);
  }

}

