import { CommonModule } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { MatIconModule } from '@angular/material/icon';
import { GitApiService } from '../../services/git-api/git-api.service';
import { SessionService } from '../../services/session/session.service';
import { IssueTrackerService } from '../../services/issue-tracker/issue-tracker.service';
import { MatButtonModule } from '@angular/material/button';
import { MatMenuModule } from '@angular/material/menu';
import { MatButtonToggleModule } from '@angular/material/button-toggle';
import { MarkdownModule } from 'ngx-markdown';
import { CardRepoComponent } from '../../components/card-repo/card-repo.component';

@Component({
  selector: 'app-projects',
  imports: [
    MatIconModule,
    CommonModule,
    MatButtonModule,
    MatMenuModule,
    MatButtonToggleModule,
    MarkdownModule,
    CardRepoComponent
  ],
  templateUrl: './projects.component.html',
  styleUrl: './projects.component.scss'
})
export class ProjectsComponent implements OnInit{
  public repositories: any;
  public selectedRepo: any;
  public isLoaded: boolean = false;

  constructor(
    private gitApiService: GitApiService,
    private sessionService: SessionService,
    private issueTrackerService: IssueTrackerService
  ){}

  async ngOnInit() {
    try{
      this.repositories = await this.gitApiService.listRepositories({
        params: {
          visibility: 'all',
          affiliation: 'owner,collaborator,organization_member',
          per_page: 100,
        },
        owner: await this.sessionService.getSession('owner')
      });

      this.repositories.forEach(async (element: any) => {
        const read = await this.newIssues(element);

        element.unread = read;
      });
    }catch(error){
      console.error(error);
    }finally{
      this.isLoaded = true;
    } 
  }

  async newIssues(data: any){
    const url = this.issueTrackerService.extractRepositoryName(data.url);
    const viewedData = await this.sessionService.getSession('viewed') || [];
    const issueTrackerData = viewedData[url.owner][url.repo] || [];

    if(!issueTrackerData){
      return data.open_issues;
    } 

    const issues = await this.gitApiService.listRepositoryIssues(data.full_name);
    const newIssues = issues.filter((issue: any) => !issueTrackerData.includes(issue.id));
    return newIssues.length;
  }
  
}

import { CommonModule } from '@angular/common';
import { Component, EventEmitter, Input, Output } from '@angular/core';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatIconModule } from '@angular/material/icon';
import { MatInputModule } from '@angular/material/input';

@Component({
  selector: 'app-select-dialog',
  imports: [
    MatFormFieldModule,
    MatIconModule,
    MatCheckboxModule,
    MatInputModule,
    CommonModule
  ],
  templateUrl: './select-dialog.component.html',
  styleUrl: './select-dialog.component.scss'
})
export class SelectDialogComponent {
  @Input() label: string = '';
  @Input() title: string = '';
  @Input() placeholder: string = '';
  @Input() data: any;

  @Output() selectedCheckboxes = new EventEmitter<any[]>();

  selectedItems: any[] = [];

  ngAfterViewInit(){
    document.addEventListener('click', this.handleOutsideClick.bind(this));
  }

  onCheckboxChange(item: any, isChecked: boolean){
    if(isChecked){
      this.selectedItems.push(item);
    }else{
      this.selectedItems = this.selectedItems.filter(i => i !== item );
    }

    this.selectedCheckboxes.emit(this.selectedItems);
  }

  showSelectDialog(event: MouseEvent){
    event.stopPropagation();

    const button = event.target as HTMLElement;
    const container = button.parentElement;

    if(container){
      const selectDialog = container?.querySelector('.select-dialog') as HTMLElement;

      if(selectDialog){
        const isVisible = selectDialog.style.display === "block";
        this.closeAllDialogs();
        selectDialog.style.display = isVisible ? 'none' : 'block';
      
        button.classList.toggle('active', !isVisible);
      }
    }
  }

  handleOutsideClick(event: MouseEvent) {
    const target = event.target as HTMLElement;

    if(!target.closest('.select-dialog-container')){
      this.closeAllDialogs();
    }
  }

  closeAllDialogs(){
    const dialogs = document.querySelectorAll('.select-dialog') as NodeListOf<HTMLElement>;
    const buttons = document.querySelectorAll('.setting-button') as NodeListOf<HTMLElement>;

    dialogs.forEach(dialog => dialog.style.display = 'none');
    buttons.forEach(button => button.classList.remove('active'));
  }

  ngOnDestroy(){
    document.removeEventListener('click', this.handleOutsideClick.bind(this));
  }

}

import { CommonModule } from '@angular/common';
import { Component, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatIconModule } from '@angular/material/icon';
import {MatSlideToggleChange, MatSlideToggleModule} from '@angular/material/slide-toggle';
import { SessionService } from '../../services/session/session.service';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatSelectChange, MatSelectModule } from '@angular/material/select';

@Component({
  selector: 'app-settings-dialog',
  imports: [
    MatIconModule,
    MatSlideToggleModule,
    CommonModule,
    FormsModule,
    MatFormFieldModule,
    MatSelectModule
  ],
  templateUrl: './settings-dialog.component.html',
  styleUrl: './settings-dialog.component.scss'
})
export class SettingsDialogComponent {
  darkMode = true;

  private sessionService = inject(SessionService);

  async ngOnInit(){
    const mode = await this.sessionService.getSession('darkMode');
    
    this.darkMode = mode;
  }

  onToggle(event: MatSlideToggleChange){
    if(typeof document !== 'undefined'){
      const container = document.querySelector('html') as HTMLElement;
    
      if(event.checked){
        container.classList.add('dark-mode');
      }else{
        container.classList.remove('dark-mode');
      }
    }
    
    this.sessionService.setSession({
      darkMode: event.checked
    });
  } 

  onChange(event: MatSelectChange){
    if(typeof document !== 'undefined'){
      const container = document.querySelector('html') as HTMLElement;

      container.classList.forEach((className) => {
        if (className.includes('palette')) {
          container.classList.remove(className);
        }
      });
  
      container.classList.add(event.value);
    }

    this.sessionService.setSession({
      theme: event.value
    });
  }
}

